const fs = require('node:fs');
const path = require('node:path');
const { withXcodeProject, withPodfile, withDangerousMod } = require('expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');

// Keeps Xcode's "Update to recommended settings" warning away from the generated
// iOS projects. The native project is regenerated by `expo prebuild`, so anything
// you would normally accept in Xcode's upgrade dialog has to be applied here.
//
// Xcode flags a project when its LastUpgradeCheck is older than the running
// Xcode, then offers the settings below. Bump XCODE_UPGRADE_CHECK when a new
// Xcode major starts showing the warning again (Xcode 27.x => 2700).
const XCODE_UPGRADE_CHECK = '2700';

const RECOMMENDED_BUILD_SETTINGS = {
  // Stays NO on purpose: React Native's "Bundle React Native code and images"
  // phase writes files (e.g. ip.txt) into the app bundle, which the user script
  // sandbox blocks. Xcode stops flagging the setting once it is set explicitly.
  ENABLE_USER_SCRIPT_SANDBOXING: 'NO',
  // Recommended default; Xcode flags projects that leave it undefined.
  DEAD_CODE_STRIPPING: 'YES',
};

const ALWAYS_RUN_PHASES = ['[Expo Dev Launcher] Strip Local Network Keys for Release'];

// Frozenholm.xcodeproj: build settings + LastUpgradeCheck.
function withAppProjectSettings(config) {
  return withXcodeProject(config, (config) => {
    const project = config.modResults;
    project.getFirstProject().firstProject.attributes.LastUpgradeCheck = XCODE_UPGRADE_CHECK;

    const configurations = project.pbxXCBuildConfigurationSection();
    for (const entry of Object.values(configurations)) {
      if (typeof entry === 'object' && entry.buildSettings) {
        Object.assign(entry.buildSettings, RECOMMENDED_BUILD_SETTINGS);
      }
    }

    // Script phases without outputs make Xcode warn "Script has ambiguous
    // dependencies". Marking them always-out-of-date is what unchecking
    // "Based on dependency analysis" does.
    const phases = project.hash.project.objects.PBXShellScriptBuildPhase ?? {};
    for (const phase of Object.values(phases)) {
      if (typeof phase === 'object' && ALWAYS_RUN_PHASES.includes(String(phase.name).replace(/^"|"$/g, ''))) {
        phase.alwaysOutOfDate = 1;
      }
    }
    return config;
  });
}

// Shared schemes carry their own LastUpgradeVersion that Xcode checks as well.
function withSchemeUpgradeVersion(config) {
  return withDangerousMod(config, [
    'ios',
    (config) => {
      const { platformProjectRoot, projectName } = config.modRequest;
      const schemesDir = path.join(platformProjectRoot, `${projectName}.xcodeproj`, 'xcshareddata', 'xcschemes');
      if (!fs.existsSync(schemesDir)) return config;

      for (const file of fs.readdirSync(schemesDir)) {
        if (!file.endsWith('.xcscheme')) continue;
        const schemePath = path.join(schemesDir, file);
        const contents = fs.readFileSync(schemePath, 'utf8');
        const updated = contents.replace(
          /LastUpgradeVersion = "\d+"/,
          `LastUpgradeVersion = "${XCODE_UPGRADE_CHECK}"`,
        );
        if (updated !== contents) fs.writeFileSync(schemePath, updated);
      }
      return config;
    },
  ]);
}

// Pods.xcodeproj is rebuilt by every `pod install`, so apply the same upgrade
// there from the Podfile's post_install hook.
function withPodsProjectSettings(config) {
  return withPodfile(config, (config) => {
    const result = mergeContents({
      tag: 'xcode-recommended-settings',
      src: config.modResults.contents,
      newSrc: [
        `    installer.pods_project.root_object.attributes['LastUpgradeCheck'] = '${XCODE_UPGRADE_CHECK}'`,
        '    installer.pods_project.build_configurations.each do |config|',
        ...Object.entries(RECOMMENDED_BUILD_SETTINGS).map(
          ([key, value]) => `      config.build_settings['${key}'] = '${value}'`,
        ),
        '    end',
      ].join('\n'),
      anchor: /post_install do \|installer\|/,
      offset: 1,
      comment: '#',
    });
    if (!result.didMerge && !result.didClear) {
      throw new Error('withXcodeRecommendedSettings: could not find `post_install do |installer|` in ios/Podfile');
    }
    config.modResults.contents = result.contents;
    return config;
  });
}

module.exports = function withXcodeRecommendedSettings(config) {
  config = withSchemeUpgradeVersion(config);
  config = withAppProjectSettings(config);
  config = withPodsProjectSettings(config);
  return config;
};
